(()=>{if(document.querySelector('script[data-gce-coverage]'))return;const here=document.currentScript;const base=here?.src?new URL('.',here.src):new URL('../assets/',location.href);const el=document.createElement('script');el.src=new URL('department-completeness.js?v=20261122-2',base).href;el.dataset.gceCoverage='true';el.defer=true;document.head.append(el)})();

/* First-visit shortcuts shared by full bilingual department profiles. Links appear only when the corresponding section exists. */
(()=>{'use strict';
 if(!document.getElementById('dp-data'))return;
 const groups={en:{title:'Start with your question',description:'Employee counts tell you who works here. Survey results tell you what respondents report. A commitment is a promise, not proof that a problem has been resolved.',links:[['who-works','Who works here?'],['experience','What do employees say about their workplace?'],['harassment','What about discrimination or harassment?'],['hiring','How do people move ahead in their careers?'],['accommodation','What about workplace adjustments?'],['recourse','How can I get help?']]},fr:{title:'Commencez par votre question',description:'Les effectifs indiquent qui travaille ici. Les sondages présentent les réponses des participants. Un engagement est une promesse, non la preuve qu’un problème est réglé.',links:[['qui-travaille','Qui travaille ici?'],['experience-fr','Que disent les employés de leur milieu de travail?'],['harcelement','Qu’en est-il de la discrimination ou du harcèlement?'],['embauche','Comment les employés progressent-ils dans leur carrière?'],['mesures-adaptation','Qu’en est-il des mesures d’adaptation au travail?'],['recours','Comment obtenir de l’aide?']]}};
 for(const [lang,info] of Object.entries(groups)){
  const root=document.getElementById('lang-'+lang),article=root?.querySelector('article');
  if(!article||root.querySelector('.gce-department-first-visit'))continue;
  const choices=info.links.filter(([id])=>{const target=document.getElementById(id);return target&&root.contains(target);});
  if(!choices.length)continue;
  const box=document.createElement('section');box.className='gce-department-first-visit';box.setAttribute('aria-label',info.title);
  const title=document.createElement('h2');title.textContent=info.title;const p=document.createElement('p');p.textContent=info.description;const ul=document.createElement('ul');
  for(const [id,label] of choices){const li=document.createElement('li'),a=document.createElement('a');a.href='#'+id;a.textContent=label;li.append(a);ul.append(li);}
  box.append(title,p,ul);article.prepend(box);
 }
 if(!document.querySelector('.gce-department-first-visit'))return;
 const style=document.createElement('style');style.textContent='.gce-department-first-visit{border:1px solid currentColor;border-radius:.5rem;padding:1rem;margin:0 0 1rem}.gce-department-first-visit h2{margin-top:0;font-size:1.2em}.gce-department-first-visit ul{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,210px),1fr));gap:.4rem;padding:0;list-style:none}.gce-department-first-visit a{display:block;padding:.5rem;border:1px solid currentColor;border-radius:.3rem}.gce-department-first-visit a:focus-visible{outline:3px solid currentColor;outline-offset:3px}';document.head.append(style);
})();

/* Compact repeated evidence gaps and expose official publications on thin profiles. */
(()=>{for(const l of ['en','fr']){const root=document.getElementById('lang-'+l);if(!root)continue;const fr=l==='fr';const pub=[...root.querySelectorAll('section')].find(s=>s.querySelector('h2[id="publications"],h2[id="publications-fr"]'));const gap=[...root.querySelectorAll('section')].find(s=>s.querySelector('h2[id="missing"],h2[id="manquant"],h2[id="donnees-manquantes"],h2[id="lacunes"]'));if(!gap||!pub)continue;const rows=[...gap.querySelectorAll('tbody tr')];if(rows.length<2)continue;const notes=rows.map(r=>r.querySelector('td')?.textContent.trim());if(!notes[0]||!notes.every(n=>n===notes[0]))continue;const p=document.createElement('p');p.textContent=notes[0];const region=gap.querySelector('.table-scroll');if(region)region.replaceWith(p);const links=document.createElement('p'),a=document.createElement('a');a.href='#'+pub.querySelector('h2').id;a.textContent=fr?'Consulter les publications officielles disponibles':'Open available official publications';links.append(a);p.after(links);const guide=root.querySelector('.dp-guide');if(guide){const info=document.createElement('p');info.textContent=fr?'Aucune mesure correspondante dans cette collection. Consultez les publications officielles ou demandez les données à l’employeur.':'No matching published measure in this collection. Consult the official publications or request data from the employer.';const jump=a.cloneNode(true);info.append(' ',jump);guide.replaceWith(info);}}})();

/* A static, employer-specific publication index prevents thin profiles from becoming dead ends. */
(()=>{const data=document.getElementById('dp-data');if(!data)return;let d;try{d=JSON.parse(data.textContent)}catch{return}if(!d.id)return;for(const l of ['en','fr']){const root=document.getElementById('lang-'+l),pub=root&&[...root.querySelectorAll('section')].find(x=>x.querySelector('h2[id="publications"],h2[id="publications-fr"]'));if(!root)continue;const fr=l==='fr',p=document.createElement('p'),a=document.createElement('a');a.href=new URL('../official-employer-publications/?org='+encodeURIComponent(d.id)+(fr?'&lang=fr':''),location.href);a.textContent=fr?'Publications officielles de cet organisme et autres pistes de recherche':'Official publications for this organization and other source routes';p.append(a);const target=pub||root.querySelector('article')||root;if(pub)pub.prepend(p);else target.prepend(p);const note=document.createElement('p');note.textContent=fr?'Les nombres de réponses au SAFF sont arrondis dans les données publiées; la population varie selon la question. Les questions conditionnelles ne portent que sur les répondants admissibles.':'Published PSES response counts are rounded; the population varies by question. Conditional questions include only eligible respondents.';const exp=root.querySelector('#experience,#experience-fr');if(exp)exp.after(note);}})();

/* Keep menu wording clear without altering source labels, section IDs or official titles. */
(()=>{const labels={"Organizational units":"Teams and branches","Unités organisationnelles":"Équipes et directions","Recourse and decisions":"Workplace complaints and decisions","Recours et décisions":"Plaintes au travail et décisions","Evidence gaps":"What data are missing","Lacunes dans les données":"Quelles données manquent","Turn evidence into action":"Use data to improve the workplace","Passer des données à l’action":"Utiliser les données pour améliorer le milieu de travail"};for(const n of document.querySelectorAll('.contents a,.mobile-jump option,article>section>h2')){const value=labels[n.textContent.trim()];if(value)n.textContent=value;}})();
